// seed: tests/seed.spec.ts

import { test, expect, type Locator, type Page } from '@playwright/test';

const MARGIN = 16;
const EPS = 1;

async function expectInsideScreen(page: Page, locator: Locator, W: number) {
  await expect(locator).toBeVisible();
  const box = await locator.boundingBox();
  expect(box).not.toBeNull();
  expect(box!.x).toBeGreaterThanOrEqual(MARGIN - EPS);
  expect(box!.x + box!.width).toBeLessThanOrEqual(W - MARGIN + EPS);
}

async function expectNoHorizontalScroll(page: Page) {
  await expect
    .poll(() => page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth))
    .toBe(true);
}

test.describe('Mobile header burger menu', () => {
  test('Burger menu controls and language list fit the screen (ru) @mobile @prod-safe (#1604a7)', async ({ page }) => {
    // 1. Open /ru as guest; W = window.innerWidth.
    await page.goto('/ru');
    const W = page.viewportSize()!.width;

    // 2. Tap the burger (menu) button in the header.
    await page.locator('header button[aria-expanded]:visible').first().click();

    // 3. Locate the login button, the sign-up button and the language switcher.
    const login = page.locator('header a[href$="/login"]:visible');
    const signup = page.locator('header a[href$="/register"]:visible');
    const langSwitcher = page.locator('header button[aria-haspopup="listbox"]:visible');
    await expectInsideScreen(page, login, W);
    await expectInsideScreen(page, signup, W);
    await expectInsideScreen(page, langSwitcher, W);
    await expect(langSwitcher).toContainText('Русский');
    await expectNoHorizontalScroll(page);

    // 4. Tap the language switcher to open the language list.
    await langSwitcher.click();
    await expect(page.getByRole('listbox')).toBeVisible();
    for (const name of ['עברית', 'English', 'Русский', 'العربية']) {
      await expectInsideScreen(page, page.getByRole('option', { name }), W);
    }
    await expectNoHorizontalScroll(page);
  });
});
